SELECT id, scope_type, scope_key, sender_id, content, created_at
FROM cms_message WHERE scope_type=#{scopeType} AND scope_key=#{scopeKey}
ORDER BY created_at ASC, id ASC

SELECT id, scope_type, scope_key, sender_id, content, created_at
FROM cms_message WHERE scope_type=#{scopeType} AND scope_key=#{scopeKey}
ORDER BY created_at DESC, id DESC LIMIT 1
